import*as THREE from'three';import{Port,materials}from'../../core/index.js';import{mesh,FACE,portQuaternion}from'../../modeling/parts.js';import{spec}from'./dimensions.js';
export function grove(host){
 const frame=new THREE.Group();frame.name='Unit3.96 physical white HY2.0-4P socket';frame.position.fromArray(spec.grove.position);frame.quaternion.copy(FACE.bottom);host.body.add(frame);
 const red=materials.plastic(spec.grove.color,{roughness:.74}),metal=materials.metal(0xb7b6a3,{roughness:.42}),box=(s,p,n,m=red)=>mesh(frame,new THREE.BoxGeometry(...s),m,p,'Unit3.96 Grove '+n),depth=6.1;
 for(const sign of[-1,1]){box([.65,5.2,depth],[sign*4.675,0,-depth/2],'side rail');box([.7,.6,3.2],[sign*3.85,2.3,-4.5],'inner guide');box([.6,.45,1.2],[sign*3.65,2.375,-1.8],'locking shoulder');}box([8.7,.65,depth],[0,-2.275,-depth/2],'floor');box([8.7,4.55,.65],[0,.325,-depth+.325],'deep dielectric rear wall');box([4.8,.45,2.3],[0,2.375,-4.3],'locking bridge');
 const contacts=[];for(let i=0;i<4;i++){contacts.push(box([.42,.42,4.3],[(i-1.5)*2,.2,-3.5],'real contact '+(i+1),metal));box([.42,1.3,.42],[(i-1.5)*2,-2.65,-5.6],'solder tail '+(i+1),metal);}
 const port=host.add(new Port({id:'grove',label:'HY2.0-4P · numbered contacts',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10,1,5.2],pins:[{n:4,name:'4',color:'black'},{n:3,name:'3',color:'red'},{n:2,name:'2',color:'yellow'},{n:1,name:'1',color:'white'}],pinGrid:{cols:4,rows:1,pitch:2,center:[0,.2],order:col=>col+1},meta:{role:'visual-connector',face:'bottom',scope:'Four physical contacts and cable attachment/pose only; no routing,conversion,voltage,current,signal,power,electrical or firmware behavior'}}));return{frame,contacts,port};
}
export function terminal(host){const frame=new THREE.Group();frame.name='Unit3.96 fixed orange shrouded male four-pin header';frame.position.fromArray(spec.terminal.position);host.body.add(frame);const orange=materials.plastic(0xf99547,{roughness:.69}),metal=materials.metal(0xb9b7aa,{roughness:.43}),parts=[],box=(s,p,n,m=orange)=>{const q=mesh(frame,new THREE.BoxGeometry(...s),m,p,'Unit3.96 fixed header '+n);parts.push(q);return q;};box([15.8,.65,5.6],[0,-9.675,-.2],'deep dielectric rear wall');for(const sign of[-1,1])box([.6,9.35,5.6],[sign*7.6,-4.675,-.2],'side cheek');box([14.6,9.35,.5],[0,-4.675,-2.75],'lower channel floor');box([14.6,7.1,.4],[0,-3.55,2.4],'front-projecting upper hood');box([14.6,.8,.4],[0,-9.1,2.4],'rear upper hood');for(const x of[-7.3,-3.96,0,3.96,7.3])box([.55,1.6,.4],[x,-7.9,2.4],'partition between four real hood latch windows');const contacts=[],tails=[];for(const x of spec.terminal.pinX){contacts.push(box([.62,7.8,.62],[x,-5.4,-1],'recessed fixed male contact pin',metal));tails.push(box([.62,.62,3.9],[x,-9.1,-2.65],'right-angle PCB solder tail',metal));}const port=host.add(new Port({id:'terminal',label:'1 / 2 / 3 / 4 · HT3.96 four-pole male header',connector:spec.terminal.connector,position:spec.terminal.position,hitSize:[15.8,1,5.6],pins:spec.terminal.names.map((name,i)=>({n:i+1,name})),pinGrid:{cols:4,rows:1,pitch:3.96,center:[0,-1],order:col=>col+1},meta:{role:'visual-connector',face:'top',pinOrderEvidence:'Own back label upper row4,3,2,1 is reversed in front view;front-view fixed header order1,2,3,4.Index is printed physical numbering only.',scope:'Fixed shrouded male header,four contacts,matching female plug and appearance pose only;no signal/power assignment,routing,voltage,current,electrical conversion or firmware behavior'}}));return{frame,parts,contacts,tails,port};}
